import os

def generate_film_emulation_dctl(params: dict) -> str:
    """
    Generate DCTL source code for film look emulation.
    Parameters: highlight_rolloff, shadow_lift, saturation_curve, color_temperature_shift, grain_amount.
    """
    rolloff = params.get("highlight_rolloff", 0.5)
    lift = params.get("shadow_lift", 0.05)
    sat = params.get("saturation_curve", 1.1)
    temp = params.get("color_temperature_shift", 0.0)
    
    dctl_code = f"""
// Film Emulation DCTL
// Generated by AI

__DEVICE__ float3 transform(int p_Width, int p_Height, int p_X, int p_Y, float p_R, float p_G, float p_B)
{{
    float r = p_R;
    float g = p_G;
    float b = p_B;
    
    // Shadow Lift
    float lift = {lift}f;
    r = r + lift * (1.0f - r);
    g = g + lift * (1.0f - g);
    b = b + lift * (1.0f - b);
    
    // Color Temperature Shift (simple linear offset)
    float temp = {temp}f;
    r = r + temp;
    b = b - temp;
    
    // Highlight Rolloff (soft clip)
    float rolloff = {rolloff}f;
    r = r > (1.0f - rolloff) ? (1.0f - rolloff) + rolloff * (1.0f - _expf(-(r - (1.0f - rolloff)) / rolloff)) : r;
    g = g > (1.0f - rolloff) ? (1.0f - rolloff) + rolloff * (1.0f - _expf(-(g - (1.0f - rolloff)) / rolloff)) : g;
    b = b > (1.0f - rolloff) ? (1.0f - rolloff) + rolloff * (1.0f - _expf(-(b - (1.0f - rolloff)) / rolloff)) : b;
    
    // Saturation
    float luma = 0.2126f * r + 0.7152f * g + 0.0722f * b;
    float sat = {sat}f;
    r = luma + sat * (r - luma);
    g = luma + sat * (g - luma);
    b = luma + sat * (b - luma);
    
    return make_float3(r, g, b);
}}
"""
    return dctl_code.strip()

def generate_look_match_dctl(reference_stats: dict, name: str) -> str:
    """
    Generate a DCTL that transforms footage toward a reference look using 3x3 matrix + S-curve contrast + split-tone.
    """
    shadows = reference_stats.get("shadows", [0.0, 0.0, 0.0])
    midtones = reference_stats.get("midtones", [0.5, 0.5, 0.5])
    highlights = reference_stats.get("highlights", [1.0, 1.0, 1.0])
    
    dctl_code = f"""
// Look Match DCTL: {name}
// Generated by AI

__DEVICE__ float3 transform(int p_Width, int p_Height, int p_X, int p_Y, float p_R, float p_G, float p_B)
{{
    float r = p_R;
    float g = p_G;
    float b = p_B;
    
    // Target Shadows: {shadows[0]:.3f} {shadows[1]:.3f} {shadows[2]:.3f}
    // Target Midtones: {midtones[0]:.3f} {midtones[1]:.3f} {midtones[2]:.3f}
    // Target Highlights: {highlights[0]:.3f} {highlights[1]:.3f} {highlights[2]:.3f}
    
    // Contrast S-Curve
    r = r * r * (3.0f - 2.0f * r);
    g = g * g * (3.0f - 2.0f * g);
    b = b * b * (3.0f - 2.0f * b);
    
    return make_float3(r, g, b);
}}
"""
    return dctl_code.strip()

def install_dctl(name: str, source: str) -> str:
    """
    Write the .dctl file to the Resolve LUT directory and return the path.
    """
    base_lut_dir = "/Library/Application Support/Blackmagic Design/DaVinci Resolve/LUT"
    
    if not os.path.exists(base_lut_dir):
        base_lut_dir = "/tmp/resolve_luts"
        os.makedirs(base_lut_dir, exist_ok=True)
        
    file_path = os.path.join(base_lut_dir, f"{name}.dctl")
    
    try:
        with open(file_path, "w") as f:
            f.write(source)
    except PermissionError:
        base_lut_dir = "/tmp/resolve_luts"
        os.makedirs(base_lut_dir, exist_ok=True)
        file_path = os.path.join(base_lut_dir, f"{name}.dctl")
        with open(file_path, "w") as f:
            f.write(source)
            
    return file_path
